// _jsNumToString mirrors ECMAScript Number::toString (spec 6.1.6.1.20) for a
// finite value. Go's strconv 'g' format uses different exponent thresholds and
// zero-pads exponents ("1e-06" vs JS "1e-6"), so we take the shortest
// round-trip digits + decimal exponent from strconv's 'e' format and reformat
// per the JS rules: fixed notation for -6 < n <= 21, exponential otherwise,
// with a sign-only (unpadded) exponent.
func _jsNumToString(f float64) string {
	if f == 0 {
		return "0" // covers +0 and -0 (JS (-0).toString() === "0")
	}
	neg := f < 0
	if neg {
		f = -f
	}
	e := strconv.FormatFloat(f, 'e', -1, 64) // "d.ddde±XX" or "de±XX"
	ei := strings.IndexByte(e, 'e')
	exp, _ := strconv.Atoi(e[ei+1:])
	digits := strings.Replace(e[:ei], ".", "", 1)
	k := len(digits) // number of significant digits
	n := exp + 1     // position of the decimal point (value = digits x 10^(n-k))
	var s string
	switch {
	case k <= n && n <= 21:
		s = digits + strings.Repeat("0", n-k)
	case 0 < n && n <= 21:
		s = digits[:n] + "." + digits[n:]
	case -6 < n && n <= 0:
		s = "0." + strings.Repeat("0", -n) + digits
	default:
		mant := digits
		if k > 1 {
			mant = digits[:1] + "." + digits[1:]
		}
		ev := n - 1
		sign := "+"
		if ev < 0 {
			sign = "-"
			ev = -ev
		}
		s = mant + "e" + sign + strconv.Itoa(ev)
	}
	if neg {
		s = "-" + s
	}
	return s
}

func _showNumber(f float64) string {
	if math.IsNaN(f) {
		return "NaN"
	}
	if math.IsInf(f, 1) {
		return "Infinity"
	}
	if math.IsInf(f, -1) {
		return "-Infinity"
	}
	s := _jsNumToString(f)
	// showNumberImpl appends ".0" iff str+".0" still parses as a number -- i.e.
	// only for plain-integer renderings (no '.', 'e', or 'E').
	if !strings.ContainsAny(s, ".eE") {
		s += ".0"
	}
	return s
}

