// Shared stable merge sort (Data.Array.sortByImpl + Data.Array.ST.sortByImpl).
// compare returns an Ordering ADT; fromOrdering maps it to an int (-1/0/1).
// xs1 is written; xs2 is scratch. Mirrors the JS mergeFromTo verbatim.
func _mergeFromTo(compare, fromOrdering func(any) any, xs1, xs2 []any, from, to int) {
	mid := from + ((to - from) >> 1)
	if mid-from > 1 {
		_mergeFromTo(compare, fromOrdering, xs2, xs1, from, mid)
	}
	if to-mid > 1 {
		_mergeFromTo(compare, fromOrdering, xs2, xs1, mid, to)
	}
	i, j, k := from, mid, from
	for i < mid && j < to {
		x, y := xs2[i], xs2[j]
		c := fromOrdering(compare(x).(func(any) any)(y)).(int)
		if c > 0 {
			xs1[k] = y
			k++
			j++
		} else {
			xs1[k] = x
			k++
			i++
		}
	}
	for i < mid {
		xs1[k] = xs2[i]
		k++
		i++
	}
	for j < to {
		xs1[k] = xs2[j]
		k++
		j++
	}
}

