func _showChar(cs string) string {
	rs := []rune(cs)
	if len(rs) == 0 {
		return "''"
	}
	code := int(rs[0])
	if code < 0x20 || code == 0x7F {
		switch code {
		case 0x07:
			return "'\\a'"
		case 0x08:
			return "'\\b'"
		case 0x0C:
			return "'\\f'"
		case 0x0A:
			return "'\\n'"
		case 0x0D:
			return "'\\r'"
		case 0x09:
			return "'\\t'"
		case 0x0B:
			return "'\\v'"
		}
		return "'\\" + strconv.Itoa(code) + "'"
	}
	if cs == "'" || cs == "\\" {
		return "'\\" + cs + "'"
	}
	return "'" + cs + "'"
}

func _showString(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	rs := []rune(s)
	for i := 0; i < len(rs); i++ {
		c := rs[i]
		code := int(c)
		if code <= 0x1F || code == 0x7F || c == '"' || c == '\\' {
			switch c {
			case '"':
				b.WriteString("\\\"")
			case '\\':
				b.WriteString("\\\\")
			case 0x07:
				b.WriteString("\\a")
			case 0x08:
				b.WriteString("\\b")
			case 0x0C:
				b.WriteString("\\f")
			case 0x0A:
				b.WriteString("\\n")
			case 0x0D:
				b.WriteString("\\r")
			case 0x09:
				b.WriteString("\\t")
			case 0x0B:
				b.WriteString("\\v")
			default:
				empty := ""
				if i+1 < len(rs) && rs[i+1] >= '0' && rs[i+1] <= '9' {
					empty = "\\&"
				}
				b.WriteString("\\" + strconv.Itoa(code) + empty)
			}
		} else {
			b.WriteRune(c)
		}
	}
	b.WriteByte('"')
	return b.String()
}

