// _mkFn turns a curried fn into an n-ary uncurried variadic: applies fn one
// argument at a time over the variadic args. (mkFn0 is special: see below.)
func _mkFn(n int, fn any) any {
	return func(args ...any) any {
		r := fn
		for i := 0; i < n; i++ {
			r = r.(func(any) any)(args[i])
		}
		return r
	}
}

// _runFn curries the application of an n-ary uncurried variadic: collects n
// arguments through unary closures, then calls the variadic with all of them.
func _runFn(n int, fn any) any {
	var collect func(acc []any) any
	collect = func(acc []any) any {
		if len(acc) == n {
			return fn.(func(...any) any)(acc...)
		}
		return func(x any) any { return collect(append(append([]any{}, acc...), x)) }
	}
	return collect(nil)
}

