var Data_Number_ceil any = func(n any) any { return math.Ceil(n.(float64)) }
var Data_Number_floor any = func(n any) any { return math.Floor(n.(float64)) }

// JS Math.round rounds half toward +Infinity (= floor(x+0.5)); Go math.Round
// rounds half away from zero. Mirror JS.
// Data_Number_round is NOT math.Floor(n+0.5): that is the classic Math.round
// polyfill bug. Wherever n+0.5 rounds UP in float64 the result is one too high
// -- round(0.49999999999999994) gave 1 where JS gives 0, and
// round(4503599627370497) gave ...98 where JS returns its argument. Compare the
// fraction against 1/2 instead; nothing is added to n.
var Data_Number_round any = func(n any) any {
	f := n.(float64)
	if math.IsInf(f, 0) || math.IsNaN(f) {
		return f
	}
	fl := math.Floor(f)
	r := fl
	if f-fl >= 0.5 {
		r = fl + 1
	}
	// JS Math.round(-0.2) is -0, and the sign of zero is observable via 1.0/x.
	if r == 0 && math.Signbit(f) {
		return math.Copysign(0, -1)
	}
	return r
}
var Data_Number_trunc any = func(n any) any { return math.Trunc(n.(float64)) }
var Data_Number_isFinite any = func(n any) any {
	f := n.(float64)
	return !math.IsInf(f, 0) && !math.IsNaN(f)
}

// fromStringImpl(str, isFinite, just, nothing): uncurried (called via runFn4).
// `Data.Number.fromString` is `parseFloat` behind an isFinite guard, and
// parseFloat is a PREFIX parser: it skips leading whitespace, takes the
// longest numeric prefix and ignores the rest. So "1.5x" is 1.5, "0x10" is 0
// (it stops at the `x`), " 1.5 " is 1.5 and "1_000" is 1 -- where Go's
// strconv accepts the underscore and answers 1000. Found by Test.Boundaries.
var _floatPrefix = regexp.MustCompile(
	`^[\s]*[+-]?(?:Infinity|(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?)`)

func _parseFloat(s string) float64 {
	m := _floatPrefix.FindString(s)
	if m == "" {
		return math.NaN()
	}
	t := strings.TrimSpace(m)
	if strings.HasSuffix(t, "Infinity") {
		if strings.HasPrefix(t, "-") {
			return math.Inf(-1)
		}
		return math.Inf(1)
	}
	f, err := strconv.ParseFloat(t, 64)
	if err != nil {
		return math.NaN()
	}
	return f
}

var Data_Number_fromStringImpl any = func(args ...any) any {
	num := _parseFloat(args[0].(string))
	isFinite := args[1].(func(any) any)
	just := args[2].(func(any) any)
	nothing := args[3]
	// No error path: _parseFloat answers NaN where parseFloat does, and the
	// isFinite guard is what turns that into Nothing -- exactly as the JS
	// foreign does.
	if isFinite(num).(bool) {
		return just(num)
	}
	return nothing
}

