// ---------------------------------------------------------------------------
// Control.Monad.ST.Uncurried (runSTFnN: like _runFn but the final application
// is wrapped in an ST thunk)
// ---------------------------------------------------------------------------

func _runSTFn(n int, fn any) any {
	var collect func(acc []any) any
	collect = func(acc []any) any {
		if len(acc) == n {
			return func() any { return fn.(func(...any) any)(acc...) }
		}
		return func(x any) any { return collect(append(append([]any{}, acc...), x)) }
	}
	return collect(nil)
}

var Control_Monad_ST_Uncurried_runSTFn1 any = func(fn any) any { return _runSTFn(1, fn) }
var Control_Monad_ST_Uncurried_runSTFn2 any = func(fn any) any { return _runSTFn(2, fn) }
var Control_Monad_ST_Uncurried_runSTFn3 any = func(fn any) any { return _runSTFn(3, fn) }
var Control_Monad_ST_Uncurried_runSTFn4 any = func(fn any) any { return _runSTFn(4, fn) }

