// In-place stable merge sort (mirrors the JS mergeFromTo). compare returns an
// Ordering ADT; fromOrdering maps it to an int (-1/0/1). Returns the STArray.
var Data_Array_ST_sortByImpl any = func(args ...any) any {
	compare := args[0].(func(any) any)
	fromOrdering := args[1].(func(any) any)
	p := args[2].(*[]any)
	xs := *p
	if len(xs) < 2 {
		return p
	}
	var mergeFromTo func(xs1, xs2 []any, from, to int)
	mergeFromTo = func(xs1, xs2 []any, from, to int) {
		mid := from + ((to - from) >> 1)
		if mid-from > 1 {
			mergeFromTo(xs2, xs1, from, mid)
		}
		if to-mid > 1 {
			mergeFromTo(xs2, xs1, mid, to)
		}
		i, j, k := from, mid, from
		for i < mid && j < to {
			x, y := xs2[i], xs2[j]
			c := fromOrdering(compare(x).(func(any) any)(y)).(int)
			if c > 0 {
				xs1[k] = y
				k++
				j++
			} else {
				xs1[k] = x
				k++
				i++
			}
		}
		for i < mid {
			xs1[k] = xs2[i]
			k++
			i++
		}
		for j < to {
			xs1[k] = xs2[j]
			k++
			j++
		}
	}
	mergeFromTo(xs, append([]any{}, xs...), 0, len(xs))
	return p
}

