// ---------------------------------------------------------------------------
// backend-go PrimOp / branch / effect helper ABI
//
// codegen lowers every BackendSyntax PrimOp and Branch test to one of these
// `any`-taking helpers (see Codegen/Go.purs). They assert operand types
// INTERNALLY, so a concretely-typed operand (a literal, or another helper's
// result) and a boxed `any` operand emit identically -- Go forbids `.(T)` on a
// concrete type, which inline assertions would hit on literal operands.
// Semantics match the Phase 1 prelude shims, so the INT64/ASTRAL divergence
// ledger is inherited verbatim (int arithmetic does NOT int32-wrap; bit ops do).
// ---------------------------------------------------------------------------

func _truthy(x any) bool { return x.(bool) }

func _isTag(v any, tag string) bool { return v.(V).Tag == tag }

func _not(a any) any    { return !a.(bool) }
func _and(a, b any) any { return a.(bool) && b.(bool) }
func _or(a, b any) any  { return a.(bool) || b.(bool) }

func _intNeg(a any) any      { return -a.(int) }
func _numNeg(a any) any      { return -a.(float64) }
func _bitNot(a any) any      { return _toInt32(^a.(int)) }
func _arrayLength(a any) any { return len(a.([]any)) }

func _intAdd(a, b any) any { return a.(int) + b.(int) }
func _intSub(a, b any) any { return a.(int) - b.(int) }
func _intMul(a, b any) any { return a.(int) * b.(int) }
func _intDiv(a, b any) any {
	x, y := a.(int), b.(int)
	if y == 0 {
		return 0
	}
	if y > 0 {
		return _floorDivPos(x, y)
	}
	return -_floorDivPos(x, -y)
}

func _numAdd(a, b any) any { return a.(float64) + b.(float64) }
func _numSub(a, b any) any { return a.(float64) - b.(float64) }
func _numMul(a, b any) any { return a.(float64) * b.(float64) }
func _numDiv(a, b any) any { return a.(float64) / b.(float64) }

func _intEq(a, b any) any { return a.(int) == b.(int) }
func _intNe(a, b any) any { return a.(int) != b.(int) }
func _intGt(a, b any) any { return a.(int) > b.(int) }
func _intGe(a, b any) any { return a.(int) >= b.(int) }
func _intLt(a, b any) any { return a.(int) < b.(int) }
func _intLe(a, b any) any { return a.(int) <= b.(int) }

func _numEq(a, b any) any { return a.(float64) == b.(float64) }
func _numNe(a, b any) any { return a.(float64) != b.(float64) }
func _numGt(a, b any) any { return a.(float64) > b.(float64) }
func _numGe(a, b any) any { return a.(float64) >= b.(float64) }
func _numLt(a, b any) any { return a.(float64) < b.(float64) }
func _numLe(a, b any) any { return a.(float64) <= b.(float64) }

func _strEq(a, b any) any { return a.(string) == b.(string) }
func _strNe(a, b any) any { return a.(string) != b.(string) }
func _strGt(a, b any) any { return a.(string) > b.(string) }
