// Native int division with PureScript semantics: div-by-zero is 0 (the JS
// foreign returns 0), truncation toward zero (Go `/` already does). Used by the
// unboxed-int-loop codegen where `/` would otherwise panic on a zero divisor.
func _intDivI(a, b int) int {
	if b == 0 {
		return 0
	}
	return a / b
}

// Immutable record update: copy the base record, overwrite the given fields.
func _recordUpdate(base any, updates map[string]any) any {
	m := base.(map[string]any)
	n := make(map[string]any, len(m))
	for k, v := range m {
		n[k] = v
	}
	for k, v := range updates {
		n[k] = v
	}
	return n
}

// Effect.Exception: an Error is map[string]any{"message","name"}; throwException
// panics with it, catchException recovers (wrapping a non-Error panic like the JS
// shim's `new Error(e.toString())`). Pulled into the build transitively by
// transformers (Control.Monad.Error.Class).
func _exnError(msg any) any { return map[string]any{"message": msg, "name": "Error"} }

